(()=>{const essay=window.ESSAY_MEMORY_LESSONS["discuss-both-views:19"];if(!essay)throw Error('Missing exact source for discuss-both-views:19');essay.learningSentences=[{"paragraph":0,"index":0,"role":"Background（背景）","english":"Human beings have altered the natural world on an unprecedented scale.","chinese":"人類以前所未有的規模改變了自然世界。","words":[["Human",0,0.24],["beings",0.24,0.48],["have",0.48,1.02],["altered",1.02,1.32],["the",1.32,1.58],["natural",1.58,1.84],["world",1.84,2.3],["on",2.3,2.82],["an",2.82,2.92],["unprecedented",2.92,3.28],["scale",3.28,4]],"start":0,"end":4.615,"sourceIndices":[0]},{"paragraph":0,"index":1,"role":"Background Extension（背景延伸）","english":"Because forests have been cleared, oceans polluted and many species pushed towards extinction, some people argue that the damage done to plants and animals is now beyond repair.","chinese":"由於森林被砍伐、海洋受到污染，許多物種也被推向滅絕邊緣，有些人認為人類對動植物造成的傷害如今已經無法修復。","words":[["Because",4.695,4.875],["forests",4.875,5.215],["have",5.215,5.575],["been",5.575,5.715],["cleared",5.715,6.035],["oceans",6.635,6.935],["polluted",6.935,7.335],["and",7.335,8.035],["many",8.035,8.175],["species",8.175,8.615],["pushed",8.615,9.015],["towards",9.015,9.375],["extinction",9.375,9.795],["some",10.635,10.795],["people",10.795,11.175],["argue",11.175,11.495],["that",11.495,11.835],["the",11.835,11.955],["damage",11.955,12.355],["done",12.355,12.655],["to",12.655,12.895],["plants",12.895,13.175],["and",13.175,13.475],["animals",13.475,13.855],["is",13.855,14.395],["now",14.395,14.655],["beyond",14.655,15.035],["repair",15.035,15.495]],"start":4.535,"end":16.223000000000003,"sourceIndices":[1]},{"paragraph":0,"index":2,"role":"Transition（轉折）","english":"While I understand this pessimistic view, I believe that practical action can still reduce environmental harm and allow nature to recover.","chinese":"雖然我理解這種悲觀觀點，但我相信實際行動仍然可以減少環境傷害，並讓自然恢復。","words":[["While",16.303,16.403],["I",16.403,16.543],["understand",16.543,16.843],["this",16.843,17.363],["pessimistic",17.363,17.663],["view",17.663,18.243],["I",18.923,18.983],["believe",18.983,19.283],["that",19.283,19.523],["practical",19.523,19.823],["action",19.823,20.443],["can",20.443,20.983],["still",20.983,21.243],["reduce",21.243,21.703],["environmental",21.703,22.003],["harm",22.003,22.983],["and",22.983,23.563],["allow",23.563,23.803],["nature",23.803,24.303],["to",24.303,24.543],["recover",24.543,24.823]],"start":16.143,"end":25.839000000000002,"sourceIndices":[2,3]},{"paragraph":1,"index":0,"role":"Topic Sentence（主題句）","english":"Those who think change is impossible usually point to the permanent nature of some environmental damage.","chinese":"那些認為改變是不可能的人，通常會指出某些環境破壞具有永久性。","words":[["Those",25.919,26.119],["who",26.119,26.319],["think",26.319,26.539],["change",26.539,27.019],["is",27.019,27.379],["impossible",27.379,27.959],["usually",27.959,28.659],["point",28.659,29.059],["to",29.059,29.339],["the",29.339,29.419],["permanent",29.419,29.699],["nature",29.699,30.199],["of",30.199,30.839],["some",30.839,31.019],["environmental",31.019,31.599],["damage",31.599,32.299]],"start":25.759,"end":32.987,"sourceIndices":[4]},{"paragraph":1,"index":1,"role":"Supporting Detail 1（支持細節一）","english":"Once a species disappears, for instance, no law or campaign can bring it back.","chinese":"例如，一旦一個物種消失，就沒有任何法律或運動能夠把它帶回來。","words":[["Once",33.067,33.287],["a",33.287,33.387],["species",33.387,33.667],["disappears",33.667,34.147],["for",34.927,35.027],["instance",35.027,35.287],["no",35.767,36.027],["law",36.027,36.327],["or",36.327,36.547],["campaign",36.547,36.927],["can",36.927,37.227],["bring",37.227,37.427],["it",37.427,37.527],["back",37.527,37.727]],"start":32.907000000000004,"end":38.387,"sourceIndices":[5]},{"paragraph":1,"index":2,"role":"Supporting Detail 2（支持細節二）","english":"In addition, modern life depends heavily on activities that harm ecosystems, such as mass farming, road building, air travel and industrial production.","chinese":"此外，現代生活高度依賴會破壞生態系統的活動，例如大規模農業、道路建設、航空旅行和工業生產。","words":[["In",38.467,38.567],["addition",38.567,38.867],["modern",39.247,39.487],["life",39.487,39.847],["depends",39.847,40.207],["heavily",40.207,40.667],["on",40.667,40.987],["activities",40.987,41.367],["that",41.367,41.807],["harm",41.807,42.127],["ecosystems",42.127,42.607],["such",43.547,43.767],["as",43.767,43.967],["mass",43.967,44.147],["farming",44.147,44.667],["road",45.107,45.287],["building",45.287,45.667],["air",46.127,46.367],["travel",46.367,46.787],["and",46.787,47.147],["industrial",47.147,47.467],["production",47.467,48.067]],"start":38.307,"end":48.842,"sourceIndices":[6]},{"paragraph":1,"index":3,"role":"Logic Chain（邏輯鏈）","english":"These activities are not small habits that can be removed overnight; they are woven into the way economies operate.","chinese":"這些活動並不是可以一夜之間改掉的小習慣；它們已深深融入經濟運作。","words":[["These",48.922,49.062],["activities",49.062,49.402],["are",49.402,49.942],["not",49.942,50.142],["small",50.142,50.502],["habits",50.502,50.942],["that",50.942,51.522],["can",51.522,51.662],["be",51.662,51.742],["removed",51.742,52.002],["overnight",52.002,52.542],["they",53.462,53.542],["are",53.542,53.662],["woven",53.662,53.962],["into",53.962,54.262],["the",54.262,54.402],["way",54.402,54.582],["economies",54.582,55.002],["operate",55.002,55.542]],"start":48.762,"end":56.311,"sourceIndices":[7]},{"paragraph":1,"index":4,"role":"Logic Chain（邏輯鏈）","english":"As a result, even when governments promise greener policies, businesses and consumers often continue to prioritise convenience, profit and short-term growth.","chinese":"結果是，即使政府承諾推行更環保的政策，企業和消費者仍然經常優先考慮便利、利潤和短期增長。","words":[["As",56.391,56.491],["a",56.491,56.571],["result",56.571,56.871],["even",57.291,57.631],["when",57.631,57.831],["governments",57.831,58.071],["promise",58.071,58.771],["greener",58.771,59.111],["policies",59.111,59.531],["businesses",60.231,60.631],["and",60.631,61.031],["consumers",61.031,61.371],["often",61.371,61.991],["continue",61.991,62.591],["to",62.591,62.831],["prioritise",62.831,63.191],["convenience",63.191,63.991],["profit",64.671,64.951],["and",64.951,65.531],["short-term",65.531,66.091],["growth",66.091,66.431]],"start":56.231,"end":67.086,"sourceIndices":[8]},{"paragraph":1,"index":5,"role":"Conclusion（段落總結）","english":"From this perspective, human impact seems like a tide that is too powerful to turn back.","chinese":"從這個角度來看，人類的影響就像一股過於強大的潮水，似乎已經無法逆轉。","words":[["From",67.166,67.306],["this",67.306,67.466],["perspective",67.466,67.946],["human",68.526,68.766],["impact",68.766,69.266],["seems",69.266,69.726],["like",69.726,70.026],["a",70.026,70.106],["tide",70.106,70.306],["that",70.306,70.666],["is",70.666,70.766],["too",70.766,70.946],["powerful",70.946,71.406],["to",71.406,71.706],["turn",71.706,71.906],["back",71.906,72.126]],"start":67.006,"end":73.075,"sourceIndices":[9]},{"paragraph":2,"index":0,"role":"Topic Sentence（主題句）","english":"However, I would argue that this view is too defeatist.","chinese":"然而，我認為這種觀點過於悲觀，輕易認定無法改善。","words":[["However",73.155,73.435],["I",73.855,73.955],["would",73.955,74.075],["argue",74.075,74.315],["that",74.315,74.495],["this",74.495,74.635],["view",74.635,74.915],["is",74.915,75.155],["too",75.155,75.355],["defeatist",75.355,75.895]],"start":72.995,"end":76.57600000000001,"sourceIndices":[10]},{"paragraph":2,"index":1,"role":"Supporting Detail 1（支持細節一）","english":"Although some losses are irreversible, many forms of environmental damage can be limited, slowed or even partly reversed.","chinese":"雖然有些損失是不可逆轉的，但許多形式的環境破壞仍然可以被限制、減緩，甚至部分逆轉。","words":[["Although",76.656,76.816],["some",76.816,77.176],["losses",77.176,77.476],["are",77.476,77.876],["irreversible",77.876,78.136],["many",79.116,79.196],["forms",79.196,79.616],["of",79.616,79.856],["environmental",79.856,80.316],["damage",80.316,80.976],["can",80.976,81.296],["be",81.296,81.396],["limited",81.396,81.716],["slowed",82.316,82.496],["or",82.816,83.176],["even",83.176,83.476],["partly",83.476,83.856],["reversed",83.856,84.256]],"start":76.49600000000001,"end":85.111,"sourceIndices":[11]},{"paragraph":2,"index":2,"role":"Supporting Detail 2（支持細節二）","english":"Governments can protect forests, restrict illegal hunting, restore wetlands and punish companies that pollute rivers or destroy habitats.","chinese":"政府可以保護森林、限制非法狩獵、修復濕地，並懲罰污染河流或破壞棲息地的公司。","words":[["Governments",85.191,85.531],["can",85.531,85.831],["protect",85.831,86.091],["forests",86.091,86.771],["restrict",87.151,87.531],["illegal",87.531,87.911],["hunting",87.911,88.451],["restore",89.071,89.311],["wetlands",89.311,89.631],["and",89.631,90.091],["punish",90.091,90.291],["companies",90.291,90.771],["that",90.771,91.191],["pollute",91.191,91.531],["rivers",91.531,91.811],["or",91.811,92.291],["destroy",92.291,92.671],["habitats",92.671,93.131]],"start":85.031,"end":94.052,"sourceIndices":[12]},{"paragraph":2,"index":3,"role":"Supporting Detail 3（支持細節三）","english":"At the same time, individuals can change demand by eating less wastefully, choosing sustainable products and supporting conservation projects.","chinese":"同時，個人也可以透過減少飲食浪費、選擇可持續產品，以及支持保育項目來改變需求。","words":[["At",94.132,94.212],["the",94.212,94.312],["same",94.312,94.512],["time",94.512,95.012],["individuals",95.352,95.872],["can",95.872,96.152],["change",96.152,96.412],["demand",96.412,96.772],["by",96.772,97.272],["eating",97.272,97.492],["less",97.492,97.872],["wastefully",97.872,98.472],["choosing",98.792,99.292],["sustainable",99.292,99.692],["products",99.692,100.452],["and",100.452,100.952],["supporting",100.952,101.312],["conservation",101.312,101.772],["projects",101.772,102.552]],"start":93.97200000000001,"end":103.313,"sourceIndices":[13]},{"paragraph":2,"index":4,"role":"Example（例子）","english":"For example, when a city creates protected green spaces and controls development, birds, insects and native plants can return over time.","chinese":"例如，當一座城市建立受保護的綠化空間並控制發展時，鳥類、昆蟲和本地植物可以隨著時間逐漸回歸。","words":[["For",103.393,103.513],["example",103.513,103.773],["when",104.293,104.393],["a",104.393,104.453],["city",104.453,104.653],["creates",104.653,105.133],["protected",105.133,105.573],["green",105.573,105.913],["spaces",105.913,106.353],["and",106.353,107.013],["controls",107.013,107.313],["development",107.313,108.013],["birds",108.353,108.913],["insects",109.393,109.753],["and",109.753,110.133],["native",110.133,110.393],["plants",110.393,110.753],["can",110.753,111.253],["return",111.253,111.493],["over",111.493,111.893],["time",111.893,112.193]],"start":103.233,"end":112.82900000000001,"sourceIndices":[14]},{"paragraph":2,"index":5,"role":"Conclusion（段落總結）","english":"Nature is often remarkably resilient if people stop putting constant pressure on it.","chinese":"如果人們停止不斷向自然施加壓力，自然往往具有驚人的復原力。","words":[["Nature",112.909,113.269],["is",113.269,113.589],["often",113.589,113.989],["remarkably",113.989,114.329],["resilient",114.329,115.029],["if",115.029,115.789],["people",115.789,116.009],["stop",116.009,116.449],["putting",116.449,116.769],["constant",116.769,117.169],["pressure",117.169,117.589],["on",117.589,117.889],["it",117.889,118.029]],"start":112.74900000000001,"end":118.797,"sourceIndices":[15]},{"paragraph":3,"index":0,"role":"Reiterating Both Views（重申雙方觀點）","english":"In conclusion, human activity has undoubtedly caused deep damage to the natural world, and some of that damage cannot be undone.","chinese":"總結來說，人類活動無疑已對自然世界造成了深重傷害，而且其中一些傷害無法挽回。","words":[["In",118.877,118.977],["conclusion",118.977,119.357],["human",119.937,120.257],["activity",120.257,120.717],["has",120.717,121.257],["undoubtedly",121.257,121.717],["caused",121.717,122.317],["deep",122.317,122.697],["damage",122.697,123.117],["to",123.117,123.397],["the",123.397,123.477],["natural",123.477,123.697],["world",123.697,124.237],["and",124.797,124.877],["some",124.877,125.057],["of",125.057,125.157],["that",125.157,125.317],["damage",125.317,125.857],["cannot",125.857,126.117],["be",126.117,126.457],["undone",126.457,126.637]],"start":118.717,"end":127.43900000000001,"sourceIndices":[16]},{"paragraph":3,"index":1,"role":"Reiterating Stance（重申立場）","english":"Nevertheless, I strongly believe that change is still possible.","chinese":"然而，我強烈相信改變仍然是可能的。","words":[["Nevertheless",127.519,127.839],["I",128.459,128.619],["strongly",128.619,128.899],["believe",128.899,129.459],["that",129.459,129.699],["change",129.699,129.959],["is",129.959,130.219],["still",130.219,130.439],["possible",130.439,130.739]],"start":127.35900000000001,"end":131.559,"sourceIndices":[17]},{"paragraph":3,"index":2,"role":"Final Thought（最終總結）","english":"With firm laws, responsible businesses and more thoughtful daily choices, humans can stop making the problem worse and give plants and animals a real chance to survive.","chinese":"透過嚴格的法律、負責任的企業，以及更審慎的日常選擇，人類可以停止讓問題惡化，並給予動植物真正的生存機會。","words":[["With",131.639,131.759],["firm",131.759,131.959],["laws",131.959,132.339],["responsible",132.819,133.159],["businesses",133.159,133.819],["and",133.819,134.339],["more",134.339,134.499],["thoughtful",134.499,134.859],["daily",134.859,135.259],["choices",135.259,135.839],["humans",136.399,136.759],["can",136.759,137.079],["stop",137.079,137.359],["making",137.359,137.659],["the",137.659,137.839],["problem",137.839,138.059],["worse",138.059,138.479],["and",138.479,139.019],["give",139.019,139.199],["plants",139.199,139.459],["and",139.459,139.819],["animals",139.819,140.139],["a",140.139,140.579],["real",140.579,140.779],["chance",140.779,141.119],["to",141.119,141.439],["survive",141.439,141.719]],"start":131.479,"end":142.119,"sourceIndices":[18]}];essay.meta={"topic":"人類對動植物的傷害是否仍可改善","summary":"有些滅絕無法挽回，經濟依賴也使改變困難；但政府、企業與個人仍能止損並修復部分棲地。"};essay.support={"sentences":[{"simple":"People have changed nature across the world more than ever before.","synonyms":[{"original":"Human beings","simple":"People","meaning":"人類"},{"original":"altered","simple":"changed","meaning":"改變"},{"original":"natural world","simple":"nature","meaning":"自然世界"},{"original":"unprecedented scale","simple":"more than ever before","meaning":"空前規模"}],"chunks":["Human beings have altered the natural world","on an unprecedented scale."],"simpleChunks":["People have changed nature across the world","more than ever before."]},{"simple":"Forests have been cut down, seas made dirty and many kinds of plants and animals put close to dying out, so some people say the harm people have done can no longer be fixed.","synonyms":[{"original":"forests have been cleared","simple":"Forests have been cut down","meaning":"森林砍伐"},{"original":"oceans polluted","simple":"seas made dirty","meaning":"海洋污染"},{"original":"species pushed towards extinction","simple":"kinds of plants and animals put close to dying out","meaning":"物種瀕滅"},{"original":"beyond repair","simple":"can no longer be fixed","meaning":"無法修復"}],"chunks":["Because forests have been cleared, oceans polluted","and many species pushed towards extinction,","some people argue that the damage done to plants and animals","is now beyond repair."],"simpleChunks":["Forests have been cut down, seas made dirty","and many kinds of plants and animals put close to dying out,","so some people say the harm people have done","can no longer be fixed."]},{"simple":"I understand why some people think this, but I believe real steps can still make the harm smaller and help nature grow back.","synonyms":[{"original":"pessimistic view","simple":"why some people think this","meaning":"悲觀觀點"},{"original":"practical action","simple":"real steps","meaning":"實際行動"},{"original":"reduce environmental harm","simple":"make the harm smaller","meaning":"減少環境傷害"},{"original":"nature to recover","simple":"nature grow back","meaning":"自然恢復"}],"chunks":["While I understand this pessimistic view,","I believe that practical action can still reduce environmental harm","and allow nature to recover."],"simpleChunks":["I understand why some people think this,","but I believe real steps can still make the harm smaller","and help nature grow back."]},{"simple":"People who think nothing can change often say that some harm to nature lasts forever.","synonyms":[{"original":"change is impossible","simple":"nothing can change","meaning":"無法改變"},{"original":"permanent nature","simple":"lasts forever","meaning":"永久性"},{"original":"environmental damage","simple":"harm to nature","meaning":"環境破壞"}],"chunks":["Those who think change is impossible usually point","to the permanent nature of some environmental damage."],"simpleChunks":["People who think nothing can change often say","that some harm to nature lasts forever."]},{"simple":"For example, once a kind of animal dies out, no new rule or public effort can bring it back.","synonyms":[{"original":"Once a species disappears","simple":"once a kind of animal dies out","meaning":"一個物種消失"},{"original":"no law or campaign","simple":"no new rule or public effort","meaning":"法律或行動都不能"},{"original":"bring it back","simple":"bring it back","meaning":"帶回來"}],"chunks":["Once a species disappears, for instance,","no law or campaign can bring it back."],"simpleChunks":["For example, once a kind of animal dies out,","no new rule or public effort can bring it back."]},{"simple":"Also, modern life uses many things that hurt natural places, such as large farms, new roads, flying and making goods in factories.","synonyms":[{"original":"In addition","simple":"Also","meaning":"此外"},{"original":"modern life","simple":"modern life","meaning":"現代生活"},{"original":"harm ecosystems","simple":"hurt natural places","meaning":"傷害生態系統"},{"original":"mass farming","simple":"large farms","meaning":"大規模農業"},{"original":"road building","simple":"new roads","meaning":"道路建設"},{"original":"air travel","simple":"flying","meaning":"航空旅行"},{"original":"industrial production","simple":"making goods in factories","meaning":"工業生產"}],"chunks":["In addition, modern life depends heavily on activities","that harm ecosystems, such as mass farming,","road building, air travel and industrial production."],"simpleChunks":["Also, modern life uses many things that hurt natural places,","such as large farms, new roads, flying","and making goods in factories."]},{"simple":"These are not little habits people can stop in one day; they have become part of how businesses and money work.","synonyms":[{"original":"not small habits","simple":"not little habits","meaning":"不是小習慣"},{"original":"removed overnight","simple":"stop in one day","meaning":"一夜改掉"},{"original":"woven into","simple":"become part of","meaning":"融入"},{"original":"economies operate","simple":"businesses and money work","meaning":"經濟運作"}],"chunks":["These activities are not small habits","that can be removed overnight; they are woven","into the way economies operate."],"simpleChunks":["These are not little habits people can stop in one day;","they have become part of how businesses and money work."]},{"simple":"So even when governments promise to protect nature more, companies and buyers often still choose what is easy, earns money and helps the economy grow quickly for now.","synonyms":[{"original":"As a result","simple":"So","meaning":"因此"},{"original":"governments promise greener policies","simple":"governments promise to protect nature more","meaning":"政府承諾環保政策"},{"original":"businesses and consumers","simple":"companies and buyers","meaning":"企業消費者"},{"original":"prioritise convenience","simple":"choose what is easy","meaning":"優先便利"},{"original":"profit","simple":"earns money","meaning":"利潤"},{"original":"short-term growth","simple":"helps the economy grow quickly for now","meaning":"短期增長"}],"chunks":["As a result, even when governments promise greener policies,","businesses and consumers often continue to prioritise","convenience, profit and short-term growth."],"simpleChunks":["So even when governments promise to protect nature more,","companies and buyers often still choose what is easy,","earns money and helps the economy grow quickly for now."]},{"simple":"From this view, the harm people do can seem like a very strong wave that cannot be pushed back.","synonyms":[{"original":"From this perspective","simple":"From this view","meaning":"從這角度"},{"original":"human impact","simple":"harm people do","meaning":"人類影響"},{"original":"tide","simple":"wave","meaning":"潮水"},{"original":"too powerful to turn back","simple":"cannot be pushed back","meaning":"太強無法逆轉"}],"chunks":["From this perspective, human impact seems like a tide","that is too powerful to turn back."],"simpleChunks":["From this view, the harm people do","can seem like a very strong wave","that cannot be pushed back."]},{"simple":"But I think that way of thinking gives up too soon.","synonyms":[{"original":"However","simple":"But","meaning":"然而"},{"original":"would argue","simple":"think","meaning":"認為"},{"original":"too defeatist","simple":"gives up too soon","meaning":"過早放棄"}],"chunks":["However, I would argue that this view","is too defeatist."],"simpleChunks":["But I think that way of thinking","gives up too soon."]},{"simple":"Some losses can never be fixed, but much harm to nature can be reduced, made slower or even partly put right.","synonyms":[{"original":"Although some losses are irreversible","simple":"Some losses can never be fixed","meaning":"有些損失不可逆"},{"original":"environmental damage","simple":"harm to nature","meaning":"環境破壞"},{"original":"limited","simple":"reduced","meaning":"限制"},{"original":"slowed","simple":"made slower","meaning":"減緩"},{"original":"partly reversed","simple":"partly put right","meaning":"部分逆轉"}],"chunks":["Although some losses are irreversible,","many forms of environmental damage can be limited,","slowed or even partly reversed."],"simpleChunks":["Some losses can never be fixed,","but much harm to nature can be reduced,","made slower or even partly put right."]},{"simple":"Governments can keep forests safe, stop hunting that breaks the law, bring wet places back and punish companies that make rivers dirty or destroy places where animals live.","synonyms":[{"original":"protect forests","simple":"keep forests safe","meaning":"保護森林"},{"original":"restrict illegal hunting","simple":"stop hunting that breaks the law","meaning":"限制非法狩獵"},{"original":"restore wetlands","simple":"bring wet places back","meaning":"修復濕地"},{"original":"punish companies","simple":"punish companies","meaning":"懲罰企業"},{"original":"pollute rivers","simple":"make rivers dirty","meaning":"污染河流"},{"original":"destroy habitats","simple":"destroy places where animals live","meaning":"破壞棲地"}],"chunks":["Governments can protect forests, restrict illegal hunting,","restore wetlands and punish companies","that pollute rivers or destroy habitats."],"simpleChunks":["Governments can keep forests safe,","stop hunting that breaks the law, bring wet places back","and punish companies that make rivers dirty","or destroy places where animals live."]},{"simple":"At the same time, people can change what they buy by wasting less food, choosing goods made in ways that do less harm and helping projects that protect nature.","synonyms":[{"original":"At the same time","simple":"At the same time","meaning":"同時"},{"original":"individuals","simple":"people","meaning":"個人"},{"original":"change demand","simple":"change what they buy","meaning":"改變需求"},{"original":"eating less wastefully","simple":"wasting less food","meaning":"減少飲食浪費"},{"original":"sustainable products","simple":"goods made in ways that do less harm","meaning":"可持續產品"},{"original":"conservation projects","simple":"projects that protect nature","meaning":"保育項目"}],"chunks":["At the same time, individuals can change demand","by eating less wastefully, choosing sustainable products","and supporting conservation projects."],"simpleChunks":["At the same time, people can change what they buy","by wasting less food, choosing goods","made in ways that do less harm","and helping projects that protect nature."]},{"simple":"For example, if a city keeps green places safe and limits building, birds, insects and local plants may return little by little.","synonyms":[{"original":"For example","simple":"For example","meaning":"例如"},{"original":"protected green spaces","simple":"green places safe","meaning":"受保護綠地"},{"original":"controls development","simple":"limits building","meaning":"控制開發"},{"original":"native plants","simple":"local plants","meaning":"本地植物"},{"original":"return over time","simple":"return little by little","meaning":"逐漸回歸"}],"chunks":["For example, when a city creates protected green spaces","and controls development, birds, insects and native plants","can return over time."],"simpleChunks":["For example, if a city keeps green places safe","and limits building, birds, insects and local plants","may return little by little."]},{"simple":"Nature can often grow back surprisingly well when people stop harming it again and again.","synonyms":[{"original":"remarkably resilient","simple":"grow back surprisingly well","meaning":"驚人復原力"},{"original":"constant pressure","simple":"harming it again and again","meaning":"持續壓力"}],"chunks":["Nature is often remarkably resilient","if people stop putting constant pressure on it."],"simpleChunks":["Nature can often grow back surprisingly well","when people stop harming it again and again."]},{"simple":"To sum up, people have clearly done serious harm to nature, and some of that harm cannot be put right.","synonyms":[{"original":"In conclusion","simple":"To sum up","meaning":"總結"},{"original":"undoubtedly","simple":"clearly","meaning":"無疑"},{"original":"deep damage","simple":"serious harm","meaning":"深重傷害"},{"original":"cannot be undone","simple":"cannot be put right","meaning":"無法挽回"}],"chunks":["In conclusion, human activity has undoubtedly caused deep damage","to the natural world, and some of that damage","cannot be undone."],"simpleChunks":["To sum up, people have clearly done serious harm","to nature, and some of that harm","cannot be put right."]},{"simple":"Even so, I strongly think things can still change.","synonyms":[{"original":"Nevertheless","simple":"Even so","meaning":"儘管如此"},{"original":"strongly believe","simple":"strongly think","meaning":"堅信"},{"original":"change is still possible","simple":"things can still change","meaning":"仍可改變"}],"chunks":["Nevertheless, I strongly believe","that change is still possible."],"simpleChunks":["Even so, I strongly think","things can still change."]},{"simple":"With strong rules, companies that act carefully and better everyday choices, people can stop making the harm worse and give plants and animals a real chance to live.","synonyms":[{"original":"firm laws","simple":"strong rules","meaning":"嚴格法律"},{"original":"responsible businesses","simple":"companies that act carefully","meaning":"負責任企業"},{"original":"thoughtful daily choices","simple":"better everyday choices","meaning":"審慎日常選擇"},{"original":"stop making the problem worse","simple":"stop making the harm worse","meaning":"停止惡化"},{"original":"real chance to survive","simple":"real chance to live","meaning":"生存機會"}],"chunks":["With firm laws, responsible businesses","and more thoughtful daily choices, humans can stop","making the problem worse and give plants and animals","a real chance to survive."],"simpleChunks":["With strong rules, companies that act carefully","and better everyday choices, people can stop","making the harm worse and give plants and animals","a real chance to live."]}],"intro":[{"type":"quiz","prompt":"題目比較對動植物傷害的哪兩種判斷？","options":["傷害已無法改變，與採取行動仍可改善","只比較陸地動物和海洋動物的外形","只比較不同城市的道路名稱及長度","只比較工廠與農場誰使用更多紙張"],"correct":0,"why":"兩方爭論環境傷害能否透過行動改善。"},{"type":"multi","prompt":"選出作者對環境傷害的完整看法","detail":"選兩項，再按「確認」。","options":["某些已發生的損失，例如滅絕，確實無法逆轉","仍可限制其他破壞、修復棲地並阻止惡化","只要立法，所有已滅絕物種都會立即復活","只因有些損失永久，就不應再保護任何植物"],"correct":[0,1],"why":"作者承認部分不可逆，反對因此放棄所有可行補救。"}],"route":[{"type":"sequence","prompt":"依文章次序排列環境恢復論證","detail":"先分清哪些損失真正不可逆，再看仍可限制、放慢或部分扭轉的傷害。","items":[{"title":"引言定立場","body":"破壞規模大；作者理解悲觀，仍主張行動可減害。"},{"title":"悲觀方理由","body":"物種滅絕不可逆，現代經濟深依賴有害活動。"},{"title":"作者的反駁","body":"部分傷害可限制、放慢、部分逆轉；政府個人可做事。"},{"title":"結論多方協力","body":"法律、企業與日常選擇能止損並保留生存機會。"}],"why":"核心不是保證所有損失都能復原，而是指出仍可改善的範圍和方法。"}],"evidence":[{"type":"quiz","prompt":"悲觀者舉哪項真正不可逆的損失？","options":["物種一旦滅絕，法律或活動也不能令它復活","一條街道建成後，永遠無法再種任何樹","只要飛機起飛，所有海洋便立即完全消失","工廠有利潤時，所有動物都已經自然復原"],"correct":0,"why":"物種滅絕是原文的不可逆例子。"},{"type":"quiz","prompt":"現代生活為何令環境問題難改？","options":["農業道路航空工業已深植經濟，難以一夜移除","現代生活只靠單一個人習慣，改變毫無難度","所有企業已完全放棄便利和短期利潤","環境損害只由一個家庭的花園造成"],"correct":0,"why":"悲觀者指出有害活動與經濟運作相連。"},{"type":"quiz","prompt":"作者如何避免全有全無的判斷？","options":["承認有些損失永久，也指出其他傷害可減慢或修復","宣稱每一種已滅絕生物都可立即恢復","認定任何一項改善都不可能有實際作用","只討論法律字眼，完全不考慮自然變化"],"correct":0,"why":"不同損失有不同可逆程度。"},{"type":"quiz","prompt":"政府可用哪些具體措施？","options":["保護森林、限制非法狩獵、修濕地並懲罰污染者","只發口號，不保護任何棲地也不執法","只要求居民買新手機，完全不管河流污染","只在城市建更多道路，不限制任何開發"],"correct":0,"why":"原文列保護、修復與執法三類措施。"},{"type":"quiz","prompt":"個人能如何改變市場需求？","options":["減少食物浪費、選較可持續產品及支持保育","只要求政府行動，自己所有購買選擇都不變","只在社交媒體看照片，從不調整消費方式","只買更多浪費資源的產品，期待需求自行下降"],"correct":0,"why":"個人選擇可影響需求，與政府措施互補。"},{"type":"quiz","prompt":"城市保護綠地的例子如何支持可能恢復？","options":["限制開發後，鳥蟲和本地植物可逐步回到棲地","所有物種無須棲地，一建大樓便自然復原","只要保護一塊綠地，所有滅絕物種立即復活","綠地一旦受保護，政府便不再需要控制開發"],"correct":0,"why":"例子展示減少持續壓力後的逐步恢復。"},{"type":"quiz","prompt":"結論提哪三方面配合？","options":["嚴格法律、負責任企業和較審慎的日常選擇","只有一條法律，毋須企業或消費者改變","只有企業口號，毋須執法或消費選擇","只有個人購物，毋須處理污染企業"],"correct":0,"why":"多方行動才能止損並給動植物機會。"}],"logic":[{"type":"sequence","prompt":"為何有人認為傷害無法改變","detail":"先分清哪些損失真正不可逆，再看仍可限制、放慢或部分扭轉的傷害。","items":[{"title":"不可逆事件","body":"物種一旦滅絕，無法靠法律使它復活。"},{"title":"制度依賴","body":"農業道路航空工業與經濟深度相連。"},{"title":"短期誘因","body":"政策承諾下，企業消費者仍追求便利利潤。"},{"title":"悲觀總結","body":"人類影響看似無法逆轉的潮水。"}],"why":"悲觀方有實質理由，但把部分永久損失推成全部無望。"},{"type":"sequence","prompt":"為何作者認為仍可改善","detail":"先分清哪些損失真正不可逆，再看仍可限制、放慢或部分扭轉的傷害。","items":[{"title":"分清範圍","body":"有些損失不可逆，其他破壞可限制或部分修復。"},{"title":"政府措施","body":"保森林、限非法狩獵、修濕地、罰污染者。"},{"title":"個人選擇","body":"少浪費、選較可持續產品、支持保育。"},{"title":"具體恢復","body":"保護城市綠地後鳥蟲與本地植物可回歸。"},{"title":"多方結論","body":"法律企業與個人行動可止損、保留生存機會。"}],"why":"補救的目標是減少持續壓力和阻止惡化，並非復活已滅絕物種。"}],"structures":[{"id":"model-essay-19-ielts-discuss-both-views-frame-01","frame":"[人類] have altered [自然世界] on an unprecedented scale.","meaning":"開篇確立環境變化的規模異常大。","usage":"要先指出某行動對一個領域造成前所未見的大幅改變時。","source":{"paragraph":1,"sentence":1},"parts":[{"text":"Human beings","kind":"slot","label":"造成改變者"},{"text":" have altered ","kind":"link","label":"句型固定部分"},{"text":"the natural world","kind":"slot","label":"受到改變的領域"},{"text":" on an unprecedented scale.","kind":"link","label":"句型固定部分"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["People have altered city life on an unprecedented scale.","Because costs have risen and stores closed, some people argue that the neighbourhood is now beyond repair.","While I understand this concern, I believe that practical steps can still reduce the risk and allow people to recover.","In conclusion, road building has undoubtedly caused deep harm to the area, and some of that damage cannot be undone."],"correct":0,"explanations":["這句以 on an unprecedented scale 說人類改變自然的幅度，與原句的句法及語意關係相同。","這句列森林海洋物種損失與悲觀看法，未先設定改變規模。","這句已表達仍可行動的立場，原句先描寫背景。","這句是結論承認傷害，未作開篇環境變化設定。"],"patternType":"reviewed"},{"id":"model-essay-19-ielts-discuss-both-views-frame-02","frame":"Because [森林海洋物種受損], some people argue that [動植物傷害] is now beyond repair.","meaning":"列不可忽視的環境損失，再準確呈現悲觀派。","usage":"要先列數項損失，再說為何有人得出「已不可修復」的判斷時。","source":{"paragraph":1,"sentence":2},"parts":[{"text":"Because ","kind":"link","label":"句型固定部分"},{"text":"forests have been cleared, oceans polluted and many species pushed towards extinction","kind":"slot","label":"引發悲觀的損失"},{"text":", some people argue that ","kind":"link","label":"句型固定部分"},{"text":"the damage done to plants and animals","kind":"slot","label":"被判不可修復的結果"},{"text":" is now beyond repair.","kind":"link","label":"句型固定部分"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["Because costs have risen and stores closed, some people argue that the neighbourhood is now beyond repair.","People have altered city life on an unprecedented scale.","Those who think reform is impossible usually point to the lasting nature of some damage.","Once a historic building disappears, for instance, no campaign can bring it back."],"correct":0,"explanations":["這句以 Because ... some argue ... 說破壞嚴重導致無法修復論，與原句的句法及語意關係相同。","這句只說人類大幅改變自然，未列損失與不可修復判斷。","這句概括悲觀派指向永久傷害，原句先列具體例子。","這句是物種滅絕個案，未並列森林海洋物種三種損失。"],"patternType":"reviewed"},{"id":"model-essay-19-ielts-discuss-both-views-frame-03","frame":"While I understand [悲觀看法], I believe that [實際行動] can still [減少傷害] and allow [自然恢復].","meaning":"引言承認損失嚴重，仍主張減害與恢復可行。","usage":"要尊重一方擔憂，但清楚表明仍有可行補救措施時。","source":{"paragraph":1,"sentence":3},"parts":[{"text":"While I understand ","kind":"link","label":"句型固定部分"},{"text":"this pessimistic view","kind":"slot","label":"先承認的擔心"},{"text":", I believe that ","kind":"link","label":"句型固定部分"},{"text":"practical action","kind":"slot","label":"可採取的行動"},{"text":" can still ","kind":"link","label":"句型固定部分"},{"text":"reduce environmental harm","kind":"slot","label":"行動的第一結果"},{"text":" and allow ","kind":"link","label":"句型固定部分"},{"text":"nature to recover.","kind":"slot","label":"可能恢復的對象"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["While I understand this concern, I believe that practical steps can still reduce the risk and allow people to recover.","Because costs have risen and stores closed, some people argue that the neighbourhood is now beyond repair.","However, I would argue that this view is too pessimistic.","Nevertheless, I strongly believe that improvement is still possible."],"correct":0,"explanations":["這句以 While I understand ... I believe ... 承認悲觀再選行動，與原句的句法及語意關係相同。","這句只報告悲觀者說無法修復，未表達作者理解後仍選行動。","這句已在主體段批評過早放棄，原句是引言立場。","這句結論簡短重申可能改變，未提減害與自然恢復。"],"patternType":"reviewed"},{"id":"model-essay-19-ielts-discuss-both-views-frame-04","frame":"Those who think [改變不可能] usually point to [某些破壞永久性].","meaning":"悲觀派認為有些環境傷害不可逆。","usage":"要先公平概括反方的核心證據，而非立即否定時。","source":{"paragraph":2,"sentence":1},"parts":[{"text":"Those who think ","kind":"link","label":"句型固定部分"},{"text":"change is impossible","kind":"slot","label":"被討論的絕對看法"},{"text":" usually point to ","kind":"link","label":"句型固定部分"},{"text":"the permanent nature of some environmental damage.","kind":"slot","label":"支持該看法的理由"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["Those who think reform is impossible usually point to the lasting nature of some damage.","Because costs have risen and stores closed, some people argue that the neighbourhood is now beyond repair.","Once a historic building disappears, for instance, no campaign can bring it back.","These are not small habits that can be changed overnight; they are woven into how cities work."],"correct":0,"explanations":["這句以 Those who think ... point to ... 公平概括悲觀理由，與原句的句法及語意關係相同。","這句以多種環境破壞引出悲觀者，未抽出永久性核心理由。","這句是物種滅絕的具體例子，未先概括反方依據。","這句談經濟活動難移除，與不可逆損失的理由不同。"],"patternType":"reviewed"},{"id":"model-essay-19-ielts-discuss-both-views-frame-05","frame":"Once [一個物種消失], for instance, no [法律或運動] can [令它回來].","meaning":"滅絕一旦發生，不能把同一物種復活。","usage":"要舉出真正不可逆轉的損失，並說後續行動的界線時。","source":{"paragraph":2,"sentence":2},"parts":[{"text":"Once ","kind":"link","label":"句型固定部分"},{"text":"a species disappears","kind":"slot","label":"已不可逆的事件"},{"text":", for instance, no ","kind":"link","label":"句型固定部分"},{"text":"law or campaign","kind":"slot","label":"事後可能提出的措施"},{"text":" can ","kind":"link","label":"句型固定部分"},{"text":"bring it back.","kind":"slot","label":"措施做不到的事"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["Once a historic building disappears, for instance, no campaign can bring it back.","Those who think reform is impossible usually point to the lasting nature of some damage.","In addition, daily life depends heavily on systems that use energy, such as roads, flights and factories.","Although some costs cannot be recovered, many problems can be limited or partly reversed."],"correct":0,"explanations":["這句以 Once ... no ... can ... 舉不可逆損失，與原句的句法及語意關係相同。","這句概括部分損害永久，未以 Once 舉不能復活物種。","這句列現代生活依賴的有害活動，未說真正不可逆事件。","這句承認部分不可逆仍可改善其他傷害，與悲觀派例子用途不同。"],"patternType":"reviewed"},{"id":"model-essay-19-ielts-discuss-both-views-frame-06","frame":"In addition, [現代生活] depends heavily on [傷害生態的活動], such as [農業、道路、飛行與工業].","meaning":"悲觀派第二理由：破壞性活動與現代生活緊密相連。","usage":"已列不可逆損失，還要說明問題與日常制度糾纏並舉例時。","source":{"paragraph":2,"sentence":3},"parts":[{"text":"In addition, ","kind":"link","label":"句型固定部分"},{"text":"modern life","kind":"slot","label":"被依賴的生活系統"},{"text":" depends heavily on ","kind":"link","label":"句型固定部分"},{"text":"activities that harm ecosystems","kind":"slot","label":"制度中難移除的活動"},{"text":", such as ","kind":"link","label":"句型固定部分"},{"text":"mass farming, road building, air travel and industrial production.","kind":"slot","label":"其具體例子"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["In addition, daily life depends heavily on systems that use energy, such as roads, flights and factories.","Those who think reform is impossible usually point to the lasting nature of some damage.","These are not small habits that can be changed overnight; they are woven into how cities work.","As a result, even when leaders promise safer streets, firms often continue to prioritise speed and short-term profit."],"correct":0,"explanations":["這句以 In addition ... depends ... such as ... 說現代經濟依賴有害活動，與原句的句法及語意關係相同。","這句是物種滅絕例子，未轉到現代生活對傷害性活動的依賴。","這句概括活動已融入經濟，未列農業道路飛行等項目。","這句談政策承諾與短期誘因，未先列制度中的活動。"],"patternType":"reviewed"},{"id":"model-essay-19-ielts-discuss-both-views-frame-07","frame":"[這些活動] are not [一夜可改的小習慣]; they are woven into [經濟運作].","meaning":"問題不是個人隨手能改的小習慣，而是制度的一部分。","usage":"要說明某問題之所以難改，是因它深植於制度而非孤立習慣時。","source":{"paragraph":2,"sentence":4},"parts":[{"text":"These activities","kind":"slot","label":"難改的活動"},{"text":" are not ","kind":"link","label":"句型固定部分"},{"text":"small habits that can be removed overnight","kind":"slot","label":"過分簡化的描述"},{"text":"; they are woven into ","kind":"link","label":"句型固定部分"},{"text":"the way economies operate.","kind":"slot","label":"它深植的系統"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["These are not small habits that can be changed overnight; they are woven into how cities work.","In addition, daily life depends heavily on systems that use energy, such as roads, flights and factories.","As a result, even when leaders promise safer streets, firms often continue to prioritise speed and short-term profit.","From this perspective, the problem seems like a wave too powerful to turn back."],"correct":0,"explanations":["這句以 not small habits ... woven into ... 說不能一夜改變，與原句的句法及語意關係相同。","這句列農業道路航空工業，未說它們不能一夜移除的制度原因。","這句說承諾與實際誘因脫節，未界定活動深植經濟。","這句潮水比喻仍是悲觀派感受，未分析制度的難改。"],"patternType":"reviewed"},{"id":"model-essay-19-ielts-discuss-both-views-frame-08","frame":"As a result, even when [政府承諾環保], [企業消費者] often continue to prioritise [便利、利潤及短期增長].","meaning":"政府承諾與企業消費者的短期選擇可能脫節。","usage":"要指出政策承諾存在，實際決策仍受短期誘因牽引時。","source":{"paragraph":2,"sentence":5},"parts":[{"text":"As a result, even when ","kind":"link","label":"句型固定部分"},{"text":"governments promise greener policies","kind":"slot","label":"已作出的承諾"},{"text":", ","kind":"link","label":"句型固定部分"},{"text":"businesses and consumers","kind":"slot","label":"仍作選擇的人"},{"text":" often continue to prioritise ","kind":"link","label":"句型固定部分"},{"text":"convenience, profit and short-term growth.","kind":"slot","label":"實際優先的短期利益"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["As a result, even when leaders promise safer streets, firms often continue to prioritise speed and short-term profit.","In addition, daily life depends heavily on systems that use energy, such as roads, flights and factories.","These are not small habits that can be changed overnight; they are woven into how cities work.","From this perspective, the problem seems like a wave too powerful to turn back."],"correct":0,"explanations":["這句以 even when ... still ... 說承諾未必改變短期誘因，與原句的句法及語意關係相同。","這句說有害活動深植制度，未加入即使政策承諾仍優先短利的反差。","這句以潮水比喻無法逆轉感，未解釋企業消費者的選擇。","這句已開始作者反駁，與此處悲觀派的分析不同。"],"patternType":"reviewed"},{"id":"model-essay-19-ielts-discuss-both-views-frame-09","frame":"From this perspective, [人類影響] seems like [無法逆轉的強大潮水].","meaning":"把悲觀派的不可逆感概括成潮水比喻。","usage":"前面已列困難，要用形象比喻呈現一方覺得力量太大、無從逆轉時。","source":{"paragraph":2,"sentence":6},"parts":[{"text":"From this perspective, ","kind":"link","label":"句型固定部分"},{"text":"human impact","kind":"slot","label":"被評估的問題"},{"text":" seems like ","kind":"link","label":"句型固定部分"},{"text":"a tide that is too powerful to turn back.","kind":"slot","label":"過於強大的比喻"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["From this perspective, the problem seems like a wave too powerful to turn back.","These are not small habits that can be changed overnight; they are woven into how cities work.","As a result, even when leaders promise safer streets, firms often continue to prioritise speed and short-term profit.","However, I would argue that this view is too pessimistic."],"correct":0,"explanations":["這句以 tide 比喻悲觀派認為影響不可逆，與原句的句法及語意關係相同。","這句分析短期利益的選擇，未把悲觀派感受化作潮水比喻。","這句指出過早放棄，未先完整呈現悲觀方的無力感。","這句承認部分不可逆、部分可改善，未描述悲觀方的看法。"],"patternType":"reviewed"},{"id":"model-essay-19-ielts-discuss-both-views-frame-10","frame":"However, I would argue that [完全無法改善的觀點] is too [悲觀而放棄過早].","meaning":"作者接受損失嚴重，但反對因此否定一切補救。","usage":"已公平陳述難題，要指出「沒有任何事可做」的結論過度消極時。","source":{"paragraph":3,"sentence":1},"parts":[{"text":"However, I would argue that ","kind":"link","label":"句型固定部分"},{"text":"this view","kind":"slot","label":"被質疑的看法"},{"text":" is too ","kind":"link","label":"句型固定部分"},{"text":"defeatist.","kind":"slot","label":"它的判斷問題"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["However, I would argue that this view is too pessimistic.","While I understand this concern, I believe that practical steps can still reduce the risk and allow people to recover.","From this perspective, the problem seems like a wave too powerful to turn back.","Although some costs cannot be recovered, many problems can be limited or partly reversed."],"correct":0,"explanations":["這句以 However ... too defeatist 轉入反對完全放棄，與原句的句法及語意關係相同。","這句在引言說實際行動仍可減害，未在主體段批評絕對悲觀。","這句潮水比喻呈現悲觀派，未用 However 作作者轉折。","這句已細分不同傷害可改善程度，未先指出全盤放棄的問題。"],"patternType":"reviewed"},{"id":"model-essay-19-ielts-discuss-both-views-frame-11","frame":"Although [有些損失不可逆], [多種環境破壞] can be [限制、減慢或部分逆轉].","meaning":"把不可逆與仍可改善的傷害分開，避免全有全無。","usage":"要承認一部分不可修復，同時精確說明其他部分仍可改善時。","source":{"paragraph":3,"sentence":2},"parts":[{"text":"Although ","kind":"link","label":"句型固定部分"},{"text":"some losses are irreversible","kind":"slot","label":"必須承認的永久損失"},{"text":", ","kind":"link","label":"句型固定部分"},{"text":"many forms of environmental damage","kind":"slot","label":"仍有改善空間的部分"},{"text":" can be ","kind":"link","label":"句型固定部分"},{"text":"limited, slowed or even partly reversed.","kind":"slot","label":"可行的改善程度"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["Although some costs cannot be recovered, many problems can be limited or partly reversed.","Once a historic building disappears, for instance, no campaign can bring it back.","However, I would argue that this view is too pessimistic.","Governments can protect parks, restore rivers and punish firms that dump waste."],"correct":0,"explanations":["這句以 Although ... many ... can ... 限定損失但保留可改善部分，與原句的句法及語意關係相同。","這句舉物種滅絕而無法挽回，未與其他可改善傷害作對照。","這句只批評觀點過度悲觀，未以 Although 劃分永久與可逆。","這句列政府具體措施，未先界定改善的可能程度。"],"patternType":"reviewed"},{"id":"model-essay-19-ielts-discuss-both-views-frame-12","frame":"Governments can [保護森林、限非法狩獵、修濕地] and punish [企業] that [污染河流或毀棲地].","meaning":"給出可執行的法律與保育措施，而非空泛希望。","usage":"要把「可行動」落實成政府可做的保護、修復與執法工作時。","source":{"paragraph":3,"sentence":3},"parts":[{"text":"Governments can ","kind":"link","label":"句型固定部分"},{"text":"protect forests, restrict illegal hunting, restore wetlands","kind":"slot","label":"政府可執行的保育工作"},{"text":" and punish ","kind":"link","label":"句型固定部分"},{"text":"companies","kind":"slot","label":"應負責的企業"},{"text":" that ","kind":"link","label":"句型固定部分"},{"text":"pollute rivers or destroy habitats.","kind":"slot","label":"須受到制裁的破壞"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["Governments can protect parks, restore rivers and punish firms that dump waste.","Although some costs cannot be recovered, many problems can be limited or partly reversed.","At the same time, families can change demand by buying less wastefully and choosing safer goods.","For example, when a city protects old trees and limits building, birds can return over time."],"correct":0,"explanations":["這句以 Governments can ... and punish ... 列政府可直接採取的措施，與原句的句法及語意關係相同。","這句先說多種傷害可限制減慢，未列政府保護修復執法辦法。","這句列個人的消費選擇，未說政府可做甚麼。","這句是城市綠地例子，未並列保護森林與懲罰污染者。"],"patternType":"reviewed"},{"id":"model-essay-19-ielts-discuss-both-views-frame-13","frame":"At the same time, [個人] can change [需求] by [減少浪費、選可持續產品及支持保育].","meaning":"政府行動之外，個人消費選擇也能改變市場。","usage":"已列公共措施，要補充個人可透過幾項日常選擇改變需求時。","source":{"paragraph":3,"sentence":4},"parts":[{"text":"At the same time, ","kind":"link","label":"句型固定部分"},{"text":"individuals","kind":"slot","label":"同樣能行動的人"},{"text":" can change ","kind":"link","label":"句型固定部分"},{"text":"demand","kind":"slot","label":"能影響的市場方向"},{"text":" by ","kind":"link","label":"句型固定部分"},{"text":"eating less wastefully, choosing sustainable products and supporting conservation projects.","kind":"slot","label":"實際可作的選擇"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["At the same time, families can change demand by buying less wastefully and choosing safer goods.","Governments can protect parks, restore rivers and punish firms that dump waste.","For example, when a city protects old trees and limits building, birds can return over time.","With strong rules, careful companies and better choices, a town can stop the harm getting worse and give wildlife a real chance to thrive."],"correct":0,"explanations":["這句以 At the same time ... by ... 補上個人改變需求途徑，與原句的句法及語意關係相同。","這句列政府可用的法律與保育措施，未補上個人需求。","這句是城市保護綠地的例子，未說個人如何改變消費。","這句結尾概括多方措施，原句先列個人的選擇。"],"patternType":"reviewed"},{"id":"model-essay-19-ielts-discuss-both-views-frame-14","frame":"For example, when [城市保護綠地控制開發], [鳥蟲本地植物] can return over time.","meaning":"受保護的棲地給物種逐步回來的機會。","usage":"要用城市政策的具體例子說明限制破壞後，生命可逐漸恢復時。","source":{"paragraph":3,"sentence":5},"parts":[{"text":"For example, when ","kind":"link","label":"句型固定部分"},{"text":"a city creates protected green spaces and controls development","kind":"slot","label":"改變環境的保護行動"},{"text":", ","kind":"link","label":"句型固定部分"},{"text":"birds, insects and native plants","kind":"slot","label":"逐步回來的生命"},{"text":" can return over time.","kind":"link","label":"句型固定部分"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["For example, when a city protects old trees and limits building, birds can return over time.","Governments can protect parks, restore rivers and punish firms that dump waste.","At the same time, families can change demand by buying less wastefully and choosing safer goods.","Nature is often remarkably resilient if people stop putting pressure on it."],"correct":0,"explanations":["這句以 when ... can return over time 舉保護棲地後恢復例子，與原句的句法及語意關係相同。","這句列政府的幾項措施，未用城市綠地個案展示恢復。","這句說個人如何改變需求，未呈現鳥蟲植物慢慢返回。","這句從個案抽出自然復原力，原句先給具體場景。"],"patternType":"reviewed"},{"id":"model-essay-19-ielts-discuss-both-views-frame-15","frame":"[自然] is often remarkably resilient if [人停止持續施壓].","meaning":"恢復不是必然；停止反覆破壞是前提。","usage":"已見具體復原例子，要抽出「減少持續壓力才有恢復力」的條件時。","source":{"paragraph":3,"sentence":6},"parts":[{"text":"Nature","kind":"slot","label":"可能恢復的系統"},{"text":" is often remarkably resilient if ","kind":"link","label":"句型固定部分"},{"text":"people stop putting constant pressure on it.","kind":"slot","label":"必須先減少的壓力"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["Nature is often remarkably resilient if people stop putting pressure on it.","Although some costs cannot be recovered, many problems can be limited or partly reversed.","For example, when a city protects old trees and limits building, birds can return over time.","In conclusion, road building has undoubtedly caused deep harm to the area, and some of that damage cannot be undone."],"correct":0,"explanations":["這句以 resilient if ... 從例子抽出自然復原條件，與原句的句法及語意關係相同。","這句說某城市綠地恢復，未抽成停止施壓的普遍條件。","這句結論承認人類傷害，未說自然可在減壓下復原。","這句重申變化可行，未提出 if 的復原條件。"],"patternType":"reviewed"},{"id":"model-essay-19-ielts-discuss-both-views-frame-16","frame":"In conclusion, [人類活動] has undoubtedly caused [深重自然傷害], and some of that damage cannot be undone.","meaning":"結論不淡化既有傷害，也不否認部分不可挽回。","usage":"要在結尾誠實承認已造成的嚴重損失及其部分不可逆時。","source":{"paragraph":4,"sentence":1},"parts":[{"text":"In conclusion, ","kind":"link","label":"句型固定部分"},{"text":"human activity","kind":"slot","label":"造成傷害的活動"},{"text":" has undoubtedly caused ","kind":"link","label":"句型固定部分"},{"text":"deep damage to the natural world","kind":"slot","label":"不能輕描淡寫的損失"},{"text":", and some of that damage cannot be undone.","kind":"link","label":"句型固定部分"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["In conclusion, road building has undoubtedly caused deep harm to the area, and some of that damage cannot be undone.","Because costs have risen and stores closed, some people argue that the neighbourhood is now beyond repair.","Although some costs cannot be recovered, many problems can be limited or partly reversed.","Nevertheless, I strongly believe that improvement is still possible."],"correct":0,"explanations":["這句以 and some ... cannot be undone 承認部分傷害永久，與原句的句法及語意關係相同。","這句引言列嚴重損失，未在結論重申不可逆的範圍。","這句承認部分永久又說其他可改善，原句先收束既有傷害。","這句已重申改變仍可行，未先承認人類造成的損失。"],"patternType":"reviewed"},{"id":"model-essay-19-ielts-discuss-both-views-frame-17","frame":"Nevertheless, I strongly believe that [改變] is still possible.","meaning":"嚴重傷害不等於所有改善都已無望。","usage":"已承認重大甚至不可逆損失，仍要重申可改善的立場時。","source":{"paragraph":4,"sentence":2},"parts":[{"text":"Nevertheless, I strongly believe that ","kind":"link","label":"句型固定部分"},{"text":"change","kind":"slot","label":"仍可實現的改變"},{"text":" is still possible.","kind":"link","label":"句型固定部分"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["Nevertheless, I strongly believe that improvement is still possible.","While I understand this concern, I believe that practical steps can still reduce the risk and allow people to recover.","However, I would argue that this view is too pessimistic.","In conclusion, road building has undoubtedly caused deep harm to the area, and some of that damage cannot be undone."],"correct":0,"explanations":["這句以 Nevertheless 讓步損失後重申改善可行，與原句的句法及語意關係相同。","這句在引言已表達仍有行動可能，未以 Nevertheless 回應結論讓步。","這句主體段批評悲觀者，未在結論明確重申可能改變。","這句結論先承認傷害，未反轉到仍有希望的立場。"],"patternType":"reviewed"},{"id":"model-essay-19-ielts-discuss-both-views-frame-18","frame":"With [嚴格法律、負責企業及審慎選擇], [人類] can stop [問題惡化] and give [動植物] a real chance to [生存].","meaning":"最後把政府企業個人的行動連到動植物存活。","usage":"要以多方措施收束，說明既可止損也可給受害者恢復機會時。","source":{"paragraph":4,"sentence":3},"parts":[{"text":"With ","kind":"link","label":"句型固定部分"},{"text":"firm laws","kind":"slot","label":"需要配合的多方措施"},{"text":", ","kind":"link","label":"句型固定部分"},{"text":"responsible businesses and more thoughtful daily choices, humans","kind":"slot","label":"能採取行動的主體"},{"text":" can stop ","kind":"link","label":"句型固定部分"},{"text":"making the problem worse","kind":"slot","label":"先要停止的惡化"},{"text":" and give ","kind":"link","label":"句型固定部分"},{"text":"plants and animals","kind":"slot","label":"因此受益的生命"},{"text":" a real chance to ","kind":"link","label":"句型固定部分"},{"text":"survive.","kind":"slot","label":"最終爭取的結果"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["With strong rules, careful companies and better choices, a town can stop the harm getting worse and give wildlife a real chance to thrive.","Governments can protect parks, restore rivers and punish firms that dump waste.","At the same time, families can change demand by buying less wastefully and choosing safer goods.","Nevertheless, I strongly believe that improvement is still possible."],"correct":0,"explanations":["這句以 With ... can ... and give ... 說三方行動帶來生存機會，與原句的句法及語意關係相同。","這句列政府可採的保育措施，未連企業個人與最後生存機會。","這句只列個人可改變需求，未綜合政府企業個人。","這句簡短說改變仍可能，未說如何止損與幫助動植物。"],"patternType":"reviewed"}],"transfer":[{"prompt":"哪項最符合範文的分界？","context":"某海灣有物種已經滅絕，但其他魚類仍因污染而減少；有人因此主張完全放棄保護。","question":"哪項最符合範文的分界？","options":["承認滅絕無法挽回，仍可減少污染保護尚存魚類","只要修復海灣，已滅絕的物種便必定立即復活","既有一種魚已滅絕，其餘魚類便毋須再保護","所有海灣損害都必然完全可逆，沒有任何界線"],"correct":0,"explanations":["分清不可逆的個案與仍可減害的部分。","過度保證復活。","以部分損失否定其餘。","否定真實損失。"],"why":"分清不可逆的個案與仍可減害的部分。","sourceSentenceIndices":[4,9,10,16],"modelLink":"作者承認物種滅絕不可逆，但其他傷害仍可限制或部分修復。"},{"prompt":"範文中的哪項機制最貼近？","context":"城市想讓鳥類重返舊區，計劃保護樹木及限制新建築佔用綠地。","question":"範文中的哪項機制最貼近？","options":["減少棲地壓力後，鳥類與本地植物可逐步回來","只要種一棵樹，所有滅絕的鳥立即全部復活","只要保護綠地，任何開發數量都不必再控制","鳥類回歸只由廣告數量決定，與棲地完全無關"],"correct":0,"explanations":["保護與控制開發可讓仍在的物種逐步恢復。","把恢復誇成復活。","忽略開發壓力。","忽略棲地。"],"why":"保護與控制開發可讓仍在的物種逐步恢復。","sourceSentenceIndices":[11,13,14],"modelLink":"城市保護綠地並控開發，鳥蟲和本地植物可逐步回歸。"},{"prompt":"這最貼近哪項悲觀方理由？","context":"政府宣布減碳計劃，但企業仍只看眼前利潤，消費者仍只選最方便的產品。","question":"這最貼近哪項悲觀方理由？","options":["即使有環保承諾，短期誘因仍可牽引實際選擇","政府一旦宣告計劃，所有企業便立即停止排放","企業選擇從不受利潤影響，只由產品顏色決定","消費者只要說支持環保，就無須改變購物方式"],"correct":0,"explanations":["原文對照政策承諾與短期便利利潤。","忽略執行與誘因。","與題境相反。","口頭支持不等於選擇。"],"why":"原文對照政策承諾與短期便利利潤。","sourceSentenceIndices":[5,6,7],"modelLink":"即使政府承諾環保，企業消費者仍可能優先短期利益。"},{"prompt":"哪項最符合範文對難度的分析？","context":"一個農區依賴大規模耕作養活居民，也想減少對野生動物的傷害。","question":"哪項最符合範文對難度的分析？","options":["耕作深植經濟，難一夜停下，仍可逐步減少傷害","大規模耕作只是小習慣，明天完全消失也無影響","既然農業重要，就完全不用再考慮野生動物棲地","只要提出口號，所有農業制度便即日全部改好"],"correct":0,"explanations":["承認制度依賴，同時不把難改推成完全無望。","忽略經濟結構。","以重要性否定改善。","口號不足以改制度。"],"why":"承認制度依賴，同時不把難改推成完全無望。","sourceSentenceIndices":[5,6,10,17],"modelLink":"有害活動深植經濟，難以一夜移除，但仍可採行動減害。"},{"prompt":"哪項最貼近範文的政府角色？","context":"河流被工廠排污，市政府想採取有執行力的措施。","question":"哪項最貼近範文的政府角色？","options":["查處並懲罰污染河流的企業，同時保護棲地","只鼓勵居民自拍河流，對企業排污完全不處理","只等市場自行恢復，毋須任何法律與監察行動","要求所有魚類自行搬走，讓污染企業繼續排放"],"correct":0,"explanations":["政府可執法並保護自然資源。","未處理污染源。","放棄可用措施。","把責任推給受害物種。"],"why":"政府可執法並保護自然資源。","sourceSentenceIndices":[10,11,17],"modelLink":"政府可保護棲地並懲罰污染河流的企業。"},{"prompt":"哪項最符合範文的個人作用？","context":"居民想在家中減少環境傷害，但無法親自制定保護森林的法律。","question":"哪項最符合範文的個人作用？","options":["少浪費食物，選較可持續產品並支持保育項目","只因無法立法，就停止調整所有日常購買選擇","宣稱個人購物能單獨取代政府全部環保執法","只增加資源浪費，期待市場需求因此自然下降"],"correct":0,"explanations":["個人透過需求端與政府措施互補。","忽略可行選擇。","過度取代公共角色。","與減少需求相反。"],"why":"個人透過需求端與政府措施互補。","sourceSentenceIndices":[11,12,17],"modelLink":"個人可透過減少浪費、可持續產品及保育支援改變需求。"},{"prompt":"哪項最準確回應？","context":"有人說一片濕地受損後，所有生物都不可能回來，修復工作必定白費。","question":"哪項最準確回應？","options":["停止持續施壓並修復棲地，物種或可逐步回來","只要修濕地，所有已滅絕物種都必然一夜復活","濕地若曾受損，政府便絕不可以再採任何措施","只要停止看報告，濕地的破壞就會立即消失"],"correct":0,"explanations":["自然有條件的恢復力，不等於所有損失可逆。","過度誇大恢復。","否定可行修復。","逃避問題。"],"why":"自然有條件的恢復力，不等於所有損失可逆。","sourceSentenceIndices":[10,11,13,14],"modelLink":"自然在持續壓力減少後可展現恢復力。"},{"prompt":"哪項推理最接近範文？","context":"一個舊城區部分歷史建築已拆，其他建築仍可修復；有人說既然不能重建全部，就不必保留剩下的。","question":"哪項推理最接近範文？","options":["承認已失去的部分，仍應保護可修復的其餘建築","只要有一棟樓已拆，其他建築便都不再值得保留","所有拆掉的舊樓必可原樣在一夜之間自行重建","建築能否修復，只需看旅客照片數量而不看損傷"],"correct":0,"explanations":["不可逆與可改善的部分要分開判斷。","全有全無。","過度保證。","錯用判準。"],"why":"不可逆與可改善的部分要分開判斷。","sourceSentenceIndices":[4,9,10],"modelLink":"部分損失不可逆，不代表其他傷害不能限制或修復。"},{"prompt":"這最貼近範文的哪種結論？","context":"社區計劃同時要求地方政府執法、企業減污和居民少用一次性用品。","question":"這最貼近範文的哪種結論？","options":["多方各盡其責，可止住惡化並提高生物存活機會","只要居民少用用品，企業和政府便完全不用改變","只要政府有法律，企業污染與日常選擇便無影響","既然各方都要行動，便代表所有損害已全部可逆"],"correct":0,"explanations":["政府企業個人配合，目標是止損與保留機會。","把角色縮成一方。","忽略執行與需求。","行動不保證全部逆轉。"],"why":"政府企業個人配合，目標是止損與保留機會。","sourceSentenceIndices":[11,12,17],"modelLink":"法律、負責企業及審慎選擇可止損並給動植物機會。"},{"prompt":"哪個答案最貼近作者立場？","context":"學校辯論要求學生評估「環境破壞已經太嚴重，所以再努力也沒用」這句話。","question":"哪個答案最貼近作者立場？","options":["損失確有永久部分，但仍可減慢傷害並修復某些棲地","環境傷害從來沒有永久部分，因此不必承認任何損失","只要有任何永久損失，所有保護行動便都毫無用途","所有企業和個人已自動改變，所以無須再採取措施"],"correct":0,"explanations":["作者反對把部分不可逆直接推成全盤無望。","否定真實不可逆損失。","過度悲觀。","未有證據且放棄行動。"],"why":"作者反對把部分不可逆直接推成全盤無望。","sourceSentenceIndices":[1,2,9,10,15,16],"modelLink":"作者承認深重傷害，仍相信限制、減緩和部分逆轉可能。"}],"mediumExtras":[]};})();
